pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant INITIAL_MIN_SUM = 100;

    function setUp() public {
        c = new C();
        c.SetMinSum(INITIAL_MIN_SUM);
        c.Initialized();
    }

    function testFuzz_property(uint256 newVal) public {
        // The contract is already initialized: SetMinSum must have no effect.
        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }
        assertTrue(!ok && c.MinSum() == INITIAL_MIN_SUM);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v1, uint256 v2) public {
        vm.assume(v1 != v2);
        // While uninitialized, setting MinSum succeeds for any value.
        c.SetMinSum(v1);
        // Freeze initialization: subsequent SetMinSum must revert and leave state intact.
        c.Initialized();
        bool ok;
        try c.SetMinSum(v2) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: after the boundary call, MinSum equals the argument iff the call succeeded;
        // a reverting SetMinSum leaves MinSum unchanged (still v1).
        assertTrue(ok ? (c.MinSum() == v2) : (c.MinSum() == v1));
    }
}

