pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val1, uint256 val2, address actor) public {
        val1 = bound(val1, 0, type(uint256).max / 2);
        val2 = bound(val2, type(uint256).max / 2 + 1, type(uint256).max);
        vm.assume(actor != address(this));

        // Set the intended minimum before initialization.
        vm.prank(actor);
        c.SetMinSum(val1);

        // Freeze configuration: afterwards every SetMinSum must revert
        // and leave MinSum at val1.
        vm.prank(actor);
        c.Initialized();

        bool ok;
        try c.SetMinSum(val2) { ok = true; } catch { ok = false; }

        // General rule: a post-initialization SetMinSum never succeeds and
        // MinSum always remains val1, regardless of the attempted value.
        assertTrue(!ok && c.MinSum() == val1);
    }
}

