import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v1, uint256 v2, address actor) public {
        vm.assume(v1 != v2);
        vm.assume(actor != address(0));

        // Before initialization, SetMinSum legitimately sets MinSum.
        vm.prank(actor);
        c.SetMinSum(v1);

        // Freeze the configuration.
        vm.prank(actor);
        c.Initialized();

        // A post-initialization SetMinSum must revert and leave MinSum == v1.
        bool ok;
        vm.prank(actor);
        try c.SetMinSum(v2) { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.MinSum() == v1);
    }
}

