pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 newVal, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);
        newVal = bound(newVal, 0, 1e30);

        // configure before initialization: MinSum = amount, allowed in both versions
        c.SetMinSum(amount);
        c.Initialized();

        // user deposits exactly `amount`
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // post-initialization attempt to raise MinSum: must be a no-op
        c.SetMinSum(newVal);

        // user collects full balance: succeeds only if MinSum still equals amount
        vm.prank(actor);
        c.Collect(amount);

        assertTrue(c.balances(actor) == 0);
    }
}

