pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialVal, uint256 laterVal) public {
        c.SetMinSum(initialVal);
        c.Initialized();
        c.SetMinSum(laterVal);
        assertTrue(c.MinSum() == initialVal);
    }
}

contract InvMutTest
{
    C c;

    constructor(C _c)
    {
        c = _c;
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();
    }

    function f(uint amount) public
    {
        require(address(this).balance >= amount);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.Deposit.selector));
        assert(ok && c.balances(address(this)) == amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function runTest(LogFile _log, uint amount) public {
        require(address(this).balance >= amount);
        c.SetLogFile(address(_log));
        c.Initialized();
        uint before = c.balances(msg.sender);
        c.Deposit{value: amount}();
        assert(c.balances(msg.sender) == before + amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest
{
